package org.eclipse.kura.internal.rest.body;

import java.io.IOException;

import org.apache.commons.io.input.BoundedInputStream;
import org.eclipse.kura.internal.rest.body.annotation.MaxRequestBodySize;

import jakarta.ws.rs.WebApplicationException;
import jakarta.ws.rs.container.ResourceInfo;
import jakarta.ws.rs.core.Context;
import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.Response.Status;
import jakarta.ws.rs.ext.Provider;
import jakarta.ws.rs.ext.ReaderInterceptor;
import jakarta.ws.rs.ext.ReaderInterceptorContext;

/**
 * Enforces {@link MaxRequestBodySize} on the request bodies read by the annotated resources. The bodies are converted
 * into object trees whose size is controlled by the request, and the limit must be enforced while reading them, since
 * an oversized body exhausts the heap before the resulting object can be validated.
 */
@Provider
// the annotation is only used for the name binding, the limit is taken from the resource class
@MaxRequestBodySize(kibibytes = 0)
public class RequestBodySizeLimiter implements ReaderInterceptor {

    @Context
    private ResourceInfo resourceInfo;

    @Override
    public Object aroundReadFrom(final ReaderInterceptorContext context) throws IOException {
        // the name binding guarantees that the resource class is annotated
        final long maxRequestBodySize = this.resourceInfo.getResourceClass().getAnnotation(MaxRequestBodySize.class)
                .kibibytes() * 1024L;

        final String contentLength = context.getHeaders().getFirst(HttpHeaders.CONTENT_LENGTH);

        if (contentLength != null && isTooLarge(contentLength, maxRequestBodySize)) {
            throw new WebApplicationException(Status.REQUEST_ENTITY_TOO_LARGE);
        }

        // the body can also be sent without Content-Length (chunked), the limit is checked while reading it too.
        // The stream is allowed one byte more than the limit, so that reaching it means that the body is too large:
        // the exception is unchecked to get through the JSON reader, which turns an IOException into a 400.
        context.setInputStream(BoundedInputStream.builder() //
                .setInputStream(context.getInputStream()) //
                .setMaxCount(maxRequestBodySize + 1) //
                .setOnMaxCount((max, count) -> {
                    throw new WebApplicationException(Status.REQUEST_ENTITY_TOO_LARGE);
                }) //
                .get());

        return context.proceed();
    }

    private static boolean isTooLarge(final String contentLength, final long maxRequestBodySize) {
        try {
            return Long.parseLong(contentLength.trim()) > maxRequestBodySize;
        } catch (final NumberFormatException e) {
            return false;
        }
    }
}
